class Maybe {
  constructor(value) {
    this.$value = value;
  }

  static of(value) {
    return new Maybe(value);
  }

  isNothing() {
    return this.$value === null || this.$value === undefined;
  }

  map(fn) {
    return this.isNothing() ? this : Maybe.of(fn(this.$value));
  }

  getOrElse(fallback) {
    return this.isNothing() ? fallback : this.$value;
  }
}

